use super::*;

pub(crate) fn row_to_surface(r: &rusqlite::Row<'_>) -> Result<PlanSurface, String> {
    let get_s = |i: usize| -> Result<String, String> { r.get::<_, String>(i).map_err(|e| e.to_string()) };
    let get_o = |i: usize| -> Result<Option<String>, String> { r.get::<_, Option<String>>(i).map_err(|e| e.to_string()) };
    let json_vec = |s: Option<String>| -> Vec<String> {
        s.and_then(|v| serde_json::from_str(&v).ok()).unwrap_or_default()
    };
    Ok(PlanSurface {
        krate: get_s(0)?,
        decision: get_s(1)?,
        into: get_o(2)?,
        subjects: json_vec(get_o(3)?),
        depends_on: json_vec(get_o(4)?),
        serves_verbs: r.get::<_, i64>(5).unwrap_or(0) != 0,
        rationale: get_o(6)?,
        owner: get_o(7)?,
        status: get_s(8)?,
        notes: json_vec(get_o(9)?),
        position: r.get(10).unwrap_or(0),
        updated_at: r.get(11).unwrap_or(0),
    })
}
